INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Lernfeld 1 > Wirtschaftliche Aspekte > Wirtschaftlichkeit IT-Systeme > Kosten, Umsätze, Gewinn
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Müssen bei der Wirtschaftlichkeit von IT-Systemen immer die Anschaffungskosten berücksichtigt werden?', 2, '[{"text": "Ja", "correct": true, "because": "Grundlage der Kostenkalkulation"}, {"text": "Nein", "correct": false, "because": "Kosten sind zentral"}]'),
('00000000-0000-0000-0000-000000000000', 'Können IT-Systeme ohne Rücksicht auf die Betriebskosten wirtschaftlich sein?', 2, '[{"text": "Nein", "correct": true, "because": "Laufende Kosten beeinflussen Rentabilität"}, {"text": "Ja", "correct": false, "because": "Betriebskosten sind entscheidend"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist der Gewinn eines IT-Systems unabhängig von den erzielten Umsätzen?', 2, '[{"text": "Nein", "correct": true, "because": "Gewinn ergibt sich aus Umsatz minus Kosten"}, {"text": "Ja", "correct": false, "because": "Umsatz beeinflusst Gewinn"}]'),
('00000000-0000-0000-0000-000000000000', 'Können IT-Systeme ohne Investitionen in Wartung langfristig wirtschaftlich bleiben?', 2, '[{"text": "Nein", "correct": true, "because": "Wartung sichert Funktion und Lebensdauer"}, {"text": "Ja", "correct": false, "because": "Ohne Wartung steigen Ausfallrisiken"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind die Umsätze eines IT-Systems immer direkt messbar?', 2, '[{"text": "Nein", "correct": true, "because": "Indirekte Vorteile wie Effizienz schwer quantifizierbar"}, {"text": "Ja", "correct": false, "because": "Nicht immer direkt messbar"}]'),
-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welcher Kostenfaktor ist bei IT-Systemen am wichtigsten?', 3, '[{"text": "Anschaffungskosten", "correct": true, "because": "Grundlage der Investition"}, {"text": "Designkosten", "correct": false, "because": "Ästhetisch, nicht primär"}, {"text": "Lieferkosten", "correct": false, "because": "Sekundär"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Kennzahl misst die Wirtschaftlichkeit eines IT-Systems direkt?', 2, '[{"text": "Return on Investment (ROI)", "correct": true, "because": "Vergleicht Kosten und Nutzen"}, {"text": "Umsatzwachstum", "correct": false, "because": "Allgemeiner Indikator"}, {"text": "Anschaffungspreis", "correct": false, "because": "Nur Kostenfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Aspekt erhöht die Umsätze durch IT-Systeme oft indirekt?', 2, '[{"text": "Prozesseffizienz", "correct": true, "because": "Steigert Produktivität"}, {"text": "Systemfarbe", "correct": false, "because": "Ästhetisch"}, {"text": "Installationszeit", "correct": false, "because": "Nicht umsatzrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Kostenart fällt bei IT-Systemen regelmäßig an?', 3, '[{"text": "Wartungskosten", "correct": true, "because": "Für Betrieb und Updates nötig"}, {"text": "Einmalkosten", "correct": false, "because": "Nur bei Anschaffung"}, {"text": "Lieferkosten", "correct": false, "because": "Einmalig bei Lieferung"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist ein Hauptziel der Wirtschaftlichkeitsbetrachtung von IT-Systemen?', 2, '[{"text": "Kosten-Nutzen-Optimierung", "correct": true, "because": "Maximiert Gewinn"}, {"text": "Minimale Anschaffung", "correct": false, "because": "Nicht allein entscheidend"}, {"text": "Schnelle Lieferung", "correct": false, "because": "Logistisch"}]'),
-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Kostenarten fallen bei IT-Systemen an?', 4, '[{"text": "Anschaffungskosten", "correct": true, "because": "Für Kauf nötig"}, {"text": "Betriebskosten", "correct": true, "because": "Für Strom und Wartung"}, {"text": "Lizenzkosten", "correct": true, "because": "Für Software"}, {"text": "Transportkosten", "correct": false, "because": "Sekundär"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren beeinflussen die Wirtschaftlichkeit von IT-Systemen?', 3, '[{"text": "Kosten", "correct": true, "because": "Bestimmen Ausgaben"}, {"text": "Umsatzsteigerung", "correct": true, "because": "Erhöht Einnahmen"}, {"text": "Lebensdauer", "correct": true, "because": "Beeinflusst Rentabilität"}, {"text": "Farbe", "correct": false, "because": "Ästhetisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile können IT-Systeme für den Gewinn bringen?', 3, '[{"text": "Effizienzsteigerung", "correct": true, "because": "Senkt Betriebskosten"}, {"text": "Prozessautomatisierung", "correct": true, "because": "Reduziert Arbeitsaufwand"}, {"text": "Umsatzwachstum", "correct": true, "because": "Durch bessere Leistung"}, {"text": "Geringere Anschaffung", "correct": false, "because": "Nicht primär"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Probleme können die Wirtschaftlichkeit von IT-Systemen beeinträchtigen?', 4, '[{"text": "Hohe Wartungskosten", "correct": true, "because": "Erhöhen Ausgaben"}, {"text": "Kurze Lebensdauer", "correct": true, "because": "Verkürzt Nutzen"}, {"text": "Inkompatibilität", "correct": true, "because": "Verursacht Zusatzkosten"}, {"text": "Schnelle Lieferung", "correct": false, "because": "Logistisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Methoden helfen, die Wirtschaftlichkeit zu bewerten?', 3, '[{"text": "ROI-Berechnung", "correct": true, "because": "Misst Rendite"}, {"text": "Total Cost of Ownership (TCO)", "correct": true, "because": "Berücksichtigt Gesamtkosten"}, {"text": "Break-Even-Analyse", "correct": true, "because": "Zeigt Rentabilitätszeitpunkt"}, {"text": "Farbabstimmung", "correct": false, "because": "Ästhetisch"}]'),
-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Anschaffungskosten sind bei der Wirtschaftlichkeit entscheidend. b) Betriebskosten sind irrelevant.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Anschaffung ja, Betriebskosten wichtig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Umsätze durch IT-Systeme können indirekt steigen. b) Gewinn ist unabhängig von den Kosten.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Umsatz ja, Gewinn kostenabhängig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Wartungskosten beeinflussen die Wirtschaftlichkeit. b) IT-Systeme sind immer sofort gewinnbringend.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Wartung ja, Gewinn zeitabhängig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) ROI misst die Wirtschaftlichkeit von IT-Systemen. b) Lizenzkosten sind keine Betriebskosten.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "ROI ja, Lizenzkosten sind Betriebskosten"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Prozesseffizienz durch IT-Systeme steigert Umsätze. b) Die Lebensdauer eines Systems ist für die Wirtschaftlichkeit unwichtig.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Effizienz ja, Lebensdauer relevant"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

